        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ILeveledNpcGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.ChanceNoneGlobal, out var ChanceNoneGlobalInfo))
            {
                yield return ChanceNoneGlobalInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.LVLT, out var LVLTInfo))
            {
                yield return LVLTInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LVOG, out var LVOGInfo))
            {
                yield return LVOGInfo;
            }
            yield break;
        }
        
