        protected LeveledNpcBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static ILeveledNpcGetter LeveledNpcFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new LeveledNpcBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static ILeveledNpcGetter LeveledNpcFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return LeveledNpcFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)LeveledNpc_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)LeveledNpc_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.OPDS:
                {
                    this.ObjectPlacementDefaults = BinaryOverlayList.FactoryByArray<IObjectPlacementDefaultGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ObjectPlacementDefaultBinaryOverlay.ObjectPlacementDefaultFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: ObjectPlacementDefault_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)LeveledNpc_FieldIndex.ObjectPlacementDefaults;
                }
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)LeveledNpc_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.ONAM:
                {
                    _ONAMLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.ONAM;
                }
                case RecordTypeInts.LVMV:
                {
                    _LVMVLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVMV;
                }
                case RecordTypeInts.LVCV:
                {
                    _LVCVLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVCV;
                }
                case RecordTypeInts.LVLM:
                {
                    _LVLMLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVLM;
                }
                case RecordTypeInts.LVLG:
                {
                    _ChanceNoneGlobalLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.ChanceNoneGlobal;
                }
                case RecordTypeInts.LVLF:
                {
                    _LVLFLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVLF;
                }
                case RecordTypeInts.LLCT:
                {
                    _LLCTLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LLCT;
                }
                case RecordTypeInts.LLKC:
                {
                    _LLKCLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LLKC;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODC:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                {
                    this.Model = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)LeveledNpc_FieldIndex.Model;
                }
                case RecordTypeInts.ENLM:
                {
                    _ENLMLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.ENLM;
                }
                case RecordTypeInts.ENLT:
                {
                    _ENLTLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.ENLT;
                }
                case RecordTypeInts.ENLS:
                {
                    _ENLSLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.ENLS;
                }
                case RecordTypeInts.AUUV:
                {
                    _AUUVLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.AUUV;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    this.Conditions = BinaryOverlayList.FactoryByCountPerItem<IConditionGetter>(
                        stream: stream,
                        package: _package,
                        countLength: 4,
                        trigger: Condition_Registration.TriggerSpecs,
                        countType: RecordTypes.CITC,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        skipHeader: false);
                    return (int)LeveledNpc_FieldIndex.Conditions;
                }
                case RecordTypeInts.LVIV:
                {
                    _LVIVLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVIV;
                }
                case RecordTypeInts.LVLD:
                {
                    _LVLDLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVLD;
                }
                case RecordTypeInts.LVLO:
                {
                    _LVLOLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVLO;
                }
                case RecordTypeInts.LVLT:
                {
                    _LVLTLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVLT;
                }
                case RecordTypeInts.LVLV:
                {
                    _LVLVLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVLV;
                }
                case RecordTypeInts.LVOG:
                {
                    _LVOGLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVOG;
                }
                case RecordTypeInts.LVOV:
                {
                    _LVOVLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVOV;
                }
                case RecordTypeInts.LVLC:
                {
                    _LVLCLocation = (stream.Position - offset);
                    return (int)LeveledNpc_FieldIndex.LVLC;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
